    #[tokio::test]
    async fn recent_events_are_tenant_scoped_newest_first_and_bounded() {
        let Some(store) = connect().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id) = unique_scope("recent-events");
        // PostgreSQL `timestamptz` stores microsecond precision. The response
        // should still be exact, so make the fixture use that same precision.
        let baseline = truncate_to_postgres_microseconds(SystemTime::now());
        let mut oldest = request(&tenant_id, &repository_id, "oldest", 1);
        oldest.occurred_at = baseline - std::time::Duration::from_secs(120);
        oldest.duration_ms = 10;
        let mut middle = request(&tenant_id, &repository_id, "middle", 2);
        middle.occurred_at = baseline - std::time::Duration::from_secs(60);
        middle.duration_ms = 20;
        let mut newest = request(&tenant_id, &repository_id, "newest", 1);
        newest.occurred_at = baseline;
        newest.duration_ms = 30;
        store.record(oldest).await.expect("record oldest event");
        store.record(middle).await.expect("record middle event");
        store.record(newest).await.expect("record newest event");
        store
            .record(request(
                &format!("other-{tenant_id}"),
                &repository_id,
                "foreign",
                2,
            ))
            .await
            .expect("record foreign-tenant event");

        let events = store
            .recent_events(&tenant_id, &repository_id, 2)
            .await
            .expect("read bounded recent events");

        assert_eq!(
            events,
            vec![
                RecentTelemetryEvent {
                    kind: 1,
                    name: "newest".to_string(),
                    outcome: 1,
                    duration_ms: 30,
                    occurred_at: baseline,
                },
                RecentTelemetryEvent {
                    kind: 1,
                    name: "middle".to_string(),
                    outcome: 2,
                    duration_ms: 20,
                    occurred_at: baseline - std::time::Duration::from_secs(60),
                },
            ]
        );
    }

    #[tokio::test]
    async fn recent_events_clamp_an_oversized_request_to_the_hard_event_ceiling() {
        let Some(store) = connect().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id) = unique_scope("recent-event-ceiling");
        let baseline = SystemTime::now() - std::time::Duration::from_secs(60);
        for event_index in 0..=MAX_RECENT_EVENTS {
            let mut event = request(
                &tenant_id,
                &repository_id,
                &format!("event-{event_index}"),
                1,
            );
            event.duration_ms = event_index;
            event.occurred_at = baseline + std::time::Duration::from_secs(event_index as u64);
            store.record(event).await.expect("record telemetry event");
        }

        let events = store
            .recent_events(&tenant_id, &repository_id, MAX_RECENT_EVENTS + 950)
            .await
            .expect("read clamped recent event sample");

        assert_eq!(
            (
                events.len(),
                events
                    .first()
                    .expect("the sample is non-empty")
                    .name
                    .as_str(),
                events
                    .last()
                    .expect("the sample is non-empty")
                    .name
                    .as_str(),
                events.first().expect("the sample is non-empty").duration_ms,
                events.last().expect("the sample is non-empty").duration_ms,
            ),
            (MAX_RECENT_EVENTS as usize, "event-50", "event-1", 50, 1,)
        );
    }

